def mse(w, b, xs, ys):
    total = 0
    for i in range(len(xs)):
        e = w * xs[i] + b - ys[i]
        total = total + e * e
    return total / len(xs)

def nudge_once(w, b, xs, ys, step):
    best = mse(w, b, xs, ys)
    up = mse(w + step, b, xs, ys)
    down = mse(w - step, b, xs, ys)
    if up < best and up <= down:
        w, best = w + step, up
    elif down < best:
        w, best = w - step, down
    up = mse(w, b + step, xs, ys)
    down = mse(w, b - step, xs, ys)
    if up < best and up <= down:
        b, best = b + step, up
    elif down < best:
        b, best = b - step, down
    return (w, b)

